import{z as o,x as s,o as B,c as l,q as e,j as r,D as a,d as i,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"注册制与新股定价","description":"","frontmatter":{"title":"注册制与新股定价","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-ipo-registration.md","filePath":"quant/cn-ipo-registration.md","lastUpdated":1791413859000}'),p={name:"quant/cn-ipo-registration.md"};function d(D,E,h,c,_,u){const t=s("Mermaid");return B(),l("div",null,[E[2]||(E[2]=e('<h1 id="注册制与新股定价" tabindex="-1">注册制与新股定价 <a class="header-anchor" href="#注册制与新股定价" aria-label="Permalink to &quot;注册制与新股定价&quot;">​</a></h1><div class="epigraph"><p>注册制把发行条件从实质审批推向信息披露与询价约束；新股前五日不设涨跌幅，使上市初期的价格发现与主板 10% 走廊不是同一过程。</p><footer>—— 《证券法》（2019 年修订）注册制条款；科创板、创业板、主板注册制改革相关证监会与交易所规则；对照[科创板/创业板](/quant/star-chinext)</footer></div><p><a href="/quant/cn-bse-neeq">上一课</a>扩展了交易所层级。本课的缺口是<strong>发行制度</strong>：核准制到注册制、询价与定价、破发、以及上市初期交易规则。科创板 2019、创业板 2020、主板 2023 年注册制落地，样本必须分段。<a href="/quant/star-chinext">星创课</a>已写两板交易差异；本课写发行与上市初期定价，不重写 20% 涨跌幅全文。后课涨跌停流动性黑洞处理日常走廊，本课处理「走廊尚未生效」的前五日。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核准制下发行市盈率与通道形成隐性上限，新股上市后常连续涨停，首日收益是配给而非可交易价格。注册制下询价范围放宽，定价可以更高，破发成为可能，上市前五日不设涨跌幅（科创板自始、创业板改革后、主板注册制后，以当时规则为准），盘中临停 ±30%、±60%。问题是：新股因子（首日收益、锁定、询价参与）在制度切换后对象变了。用 2010–2018 的打新收益外推 2021 年后，是在交易另一套配给机制。</p><p>网下询价、战略配售、锁定期与出借限制（见转融通课）改变可交易供给。量化若在上市首日做动量或反转，成交规则是集合竞价 + 宽幅波动 + 临停，不是连续 10% 板。回测必须实现临停状态机。</p>',6)),(B(),r(A,null,{default:a(()=>[n(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E6%A0%B8%E5%87%86%E5%88%B6%EF%BC%9A%E5%8F%91%E8%A1%8C%E5%B8%82%E7%9B%88%E7%8E%87%E9%9A%90%E6%80%A7%E4%B8%8A%E9%99%90%22%5D%20--%3E%20LOWP%5B%22%E5%8F%91%E8%A1%8C%E4%BB%B7%E8%A2%AB%E5%8E%8B%E4%BD%8E%22%5D%0A%20%20LOWP%20--%3E%20BOARDS%5B%22%E4%B8%8A%E5%B8%82%E5%90%8E%E8%BF%9E%E7%BB%AD%E4%B8%80%E5%AD%97%E6%B6%A8%E5%81%9C%22%5D%0A%20%20BOARDS%20--%3E%20RATION%5B%22%E9%A6%96%E6%97%A5%E6%94%B6%E7%9B%8A%20%3D%20%E9%85%8D%E7%BB%99%EF%BC%8C%E9%9A%BE%E5%A4%8D%E5%88%B6%22%5D%0A%20%20SUB2%5B%22%E6%B3%A8%E5%86%8C%E5%88%B6%EF%BC%9A%E8%AF%A2%E4%BB%B7%E8%8C%83%E5%9B%B4%E6%94%BE%E5%AE%BD%22%5D%20--%3E%20P2%5B%22%E5%8F%91%E8%A1%8C%E4%BB%B7%E5%8F%AF%E4%BB%A5%E6%9B%B4%E9%AB%98%22%5D%0A%20%20P2%20--%3E%20FREE%5B%22%E5%89%8D%E4%BA%94%E6%97%A5%E4%B8%8D%E8%AE%BE%E6%B6%A8%E8%B7%8C%E5%B9%85%20%2B%20%E7%9B%98%E4%B8%AD%E4%B8%B4%E5%81%9C%22%5D%0A%20%20FREE%20--%3E%20Q%7B%22%E4%BA%8C%E7%BA%A7%E4%BE%9B%E7%BB%99%E8%83%BD%E5%90%A6%E6%89%BF%E6%8E%A5%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%83%BD%22%7C%20PRICED%5B%22%E4%B8%8A%E5%B8%82%E5%8D%B3%E5%AE%9A%E4%BB%B7%EF%BC%8C%E5%8F%AF%E8%83%BD%E5%B9%B3%E5%BC%80%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20BROKEN%5B%22%E7%A0%B4%E5%8F%91%EF%BC%9A%E7%94%B3%E8%B4%AD%E8%80%85%E6%89%BF%E6%8B%85%E6%8D%9F%E5%A4%B1%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[i(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h3 id="定价效率与破发" tabindex="-1">定价效率与破发 <a class="header-anchor" href="#定价效率与破发" aria-label="Permalink to &quot;定价效率与破发&quot;">​</a></h3><p>破发说明询价可以高于二级愿意承接的价格，不是「注册制失败」的口号度量。研究应看：发行价相对同业、换手、锁定期满解禁冲击。解禁是供给事件，类似指数调入，须用公告与生效日。把破发当情绪指标可以，但要扣发行质量与行业。</p><p><span class="marginnote">术语翻译：「破发」就是上市后价格跌破发行价——发行价是发行人与询价对象谈出来的价格，跌破它说明二级市场愿意付的钱比询价定出的低。破发不是注册制失败的证据，而是定价权从行政配给交回市场的正常现象。</span></p><p><span class="marginnote">打新收益在核准制下高度取决于中签与连板，容量极小且依赖市值配售规则。注册制后打新期望下降，方差上升。产品宣传「稳健打新」须与当时规则一致。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发行事件表：披露日、询价日、发行价、上市日、涨跌幅制度版本、战略配售与锁定期。收益：上市初期用可成交路径（含临停），不要把一字板当成人人可买的收盘价。宇宙：新股是否进入因子样本，应在上市满 N 日或进入指数之后，避免用不可复制的连板收益污染 IC。与<a href="/quant/index-constituents-history">成分历史</a>衔接：快速入选规则使新股提前进指数，被动资金在宽幅波动期交易。</p><p><span class="marginnote">数字实例：注册制新股前五日可出现 ±30%、±60% 量级的单日波动，若因子宇宙从上市第 1 日起纳入，动量与反转因子的 IC 会被这类不可复制的宽幅波动主导。常见做法是满 20 个交易日（约一个月）或纳入指数后再进宇宙，让新股先「冷却」再进样本。</span></p><p>对照国际 IPO 抑价文献（Rock、Ritter）时声明：A 股的抑价很大一块是制度配给，注册制改变的是配给强度，不是把市场变成无摩擦询价。</p><h3 id="北交所-ipo" tabindex="-1">北交所 IPO <a class="header-anchor" href="#北交所-ipo" aria-label="Permalink to &quot;北交所 IPO&quot;">​</a></h3><p>北交所发行与适当性另套，见上一课。不要把沪深主板注册制统计直接加进北证。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>发行制度决定一级谁获得筹码、二级前五日如何发现价格。涨跌停一旦生效，发现被截断，未完成的发现进入次日开盘集合竞价，见涨跌停课。注册制把更多发现提前到前五日与询价，日常 10%/20% 走廊里的连板现象减少，但未消失。因子若依赖「新股连板动量」，在注册制样本会衰减——这是制度，不是动量因子普遍死亡。</p><p>融券与战略配售出借限制，使上市初期做空更难，高估可以持续更久。这与短约束课同一通道。</p>',13)),(B(),r(A,null,{default:a(()=>[n(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Reg%5B%22%E6%B3%A8%E5%86%8C%E5%88%B6%E8%AF%A2%E4%BB%B7%22%5D%20--%3E%20P0%5B%22%E5%8F%91%E8%A1%8C%E4%BB%B7%22%5D%0A%20%20P0%20--%3E%20D5%5B%22%E5%89%8D%E4%BA%94%E6%97%A5%E4%B8%8D%E8%AE%BE%E6%B6%A8%E8%B7%8C%E5%B9%85%22%5D%0A%20%20D5%20--%3E%20Halt%5B%22%E7%9B%98%E4%B8%AD%E4%B8%B4%E5%81%9C%22%5D%0A%20%20D5%20--%3E%20Limit%5B%22%E6%AD%A4%E5%90%8E%2010%25%20%E6%88%96%2020%25%20%E8%B5%B0%E5%BB%8A%22%5D%0A%20%20Lock%5B%22%E9%94%81%E5%AE%9A%E6%9C%9F%E4%B8%8E%E5%87%BA%E5%80%9F%E9%99%90%E5%88%B6%22%5D%20--%3E%20Supply%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E4%BE%9B%E7%BB%99%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[i(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供询价串通、利益输送或规避锁定期的方法。规则以证监会与交易所现行发行承销细则为准，本课只给状态机。老股转让、CDR、红筹回归各有专章。</p><p><span class="marginnote">常见误区：以为「打新稳赚」是市场规律。核准制下它来自发行价管制造成的一级折价配给，而且要过中签率——资金量决定分到多少；注册制后破发常态化，打新变成需要甄别发行质量的主动决策，不再是无脑申购的免费午餐。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>注册制改变发行配给与上市初期发现过程；回测必须按改革日分段。</li><li>前五日不设涨跌幅 + 临停，不是主板日常走廊。</li><li>打新与新股动量的对象在核准制/注册制之间不可比。</li><li>出处：《证券法》注册制；科创板/创业板/主板改革规则；Ritter 等 IPO 抑价传统（对照用）。</li></ul>',5))])}const f=o(p,[["render",d]]);export{m as __pageData,f as default};
